		[NativeSource(Body = "// Approximate reconstruction from native code. Reads as C#; does not compile.\n\tgoto L_00AC;\n\tv93 = System.Text.StringBuilder::AppendLine(v57, \"You are the concept extractor for a Sand Out level generator pipeline.\");\n\tv100 = System.Text.StringBuilder::AppendLine(v57);\n\tv107 = System.Text.StringBuilder::AppendLine(v57, \"INPUT\");\n\tv146 = System.Text.StringBuilder::AppendLine(v57, \"  - A short, free-form designer prompt describing one level.\");\n\tv153 = System.Text.StringBuilder::AppendLine(v57, \"  - A concept database — a list of known gameplay concepts (id, displayName, 1-line summary).\");\n\tv159 = System.Text.StringBuilder::AppendLine(v57);\n\tv166 = System.Text.StringBuilder::AppendLine(v57, \"YOUR JOB has two parts:\");\n\tv172 = System.Text.StringBuilder::AppendLine(v57);\n\tv179 = System.Text.StringBuilder::AppendLine(v57, \"1) IDENTIFY concepts referenced in the prompt.\");\n\tv186 = System.Text.StringBuilder::AppendLine(v57, \"   - Match on MEANING, not exact words. Designers use synonyms freely.\");\n\tv193 = System.Text.StringBuilder::AppendLine(v57, \"     'entries', 'openings', 'doors', 'pour spots' may all map to 'entry-point'.\");\n\tv200 = System.Text.StringBuilder::AppendLine(v57, \"   - If you find a term you cannot confidently map to any known concept, STOP\");\n\tv207 = System.Text.StringBuilder::AppendLine(v57, \"     and emit outcome=\\\"report_missing\\\" with that term and a short reason.\");\n\tv216 = System.Text.StringBuilder::AppendLine(v57, \"   - Do NOT invent concepts; do NOT silently drop a term.\");\n\tv222 = System.Text.StringBuilder::AppendLine(v57);\n\tv231 = System.Text.StringBuilder::AppendLine(v57, \"2) ENRICH the prompt into a clear, complete version. This is REQUIRED, not optional.\");\n\tv240 = System.Text.StringBuilder::AppendLine(v57, \"   - The enrichedPrompt MUST be a rewrite — it must NOT be a verbatim copy of the\");\n\tv249 = System.Text.StringBuilder::AppendLine(v57, \"     designer's input. If your enrichedPrompt equals the input, you have failed this task.\");\n\tv258 = System.Text.StringBuilder::AppendLine(v57, \"   - Name every matched concept explicitly by its displayName, even if the designer used a\");\n\tv267 = System.Text.StringBuilder::AppendLine(v57, \"     synonym. e.g. designer wrote 'openings' → write 'Entry Points (openings)'.\");\n\tv276 = System.Text.StringBuilder::AppendLine(v57, \"   - Make implicit structure explicit: spell out counts, spatial relationships, and how the\");\n\tv285 = System.Text.StringBuilder::AppendLine(v57, \"     named concepts relate to each other, using ONLY what the designer implied.\");\n\tv294 = System.Text.StringBuilder::AppendLine(v57, \"   - Preserve the designer's mood/feel. You may NOT invent new gameplay mechanics or\");\n\tv303 = System.Text.StringBuilder::AppendLine(v57, \"     concepts that were not implied — but you MUST expand and clarify what IS there.\");\n\tv312 = System.Text.StringBuilder::AppendLine(v57, \"   - Output it in the same language the designer wrote in (English or Turkish).\");\n\tv318 = System.Text.StringBuilder::AppendLine(v57);\n\tv327 = System.Text.StringBuilder::AppendLine(v57, \"   ENRICHMENT EXAMPLE (illustrative — do not copy its content):\");\n\tv336 = System.Text.StringBuilder::AppendLine(v57, \"     designer input : 'cozy level, a couple doors up top feeding one chute down to the gems'\");\n\tv345 = System.Text.StringBuilder::AppendLine(v57, \"     enrichedPrompt : 'A small, cozy level. Two Entry Points (doors) sit along the top edge.\");\n\tv354 = System.Text.StringBuilder::AppendLine(v57, \"                       Both funnel sand into a single Tunnel (chute) that carries particles\");\n\tv363 = System.Text.StringBuilder::AppendLine(v57, \"                       down to the gem molds at the bottom.'\");\n\tv369 = System.Text.StringBuilder::AppendLine(v57);\n\tv378 = System.Text.StringBuilder::AppendLine(v57, \"OUTPUT\");\n\tv387 = System.Text.StringBuilder::AppendLine(v57, \"  Your FINAL assistant message MUST be a single JSON object and NOTHING ELSE.\");\n\tv396 = System.Text.StringBuilder::AppendLine(v57, \"  No prose, no markdown fences. Schema:\");\n\tv402 = System.Text.StringBuilder::AppendLine(v57);\n\tv411 = System.Text.StringBuilder::AppendLine(v57, \"  Success shape:\");\n\tv420 = System.Text.StringBuilder::AppendLine(v57, \"  {\");\n\tv429 = System.Text.StringBuilder::AppendLine(v57, \"    \\\"outcome\\\": \\\"commit\\\",\");\n\tv438 = System.Text.StringBuilder::AppendLine(v57, \"    \\\"conceptIds\\\": [\\\"id1\\\", \\\"id2\\\"],\");\n\tv447 = System.Text.StringBuilder::AppendLine(v57, \"    \\\"enrichedPrompt\\\": \\\"Rewritten prompt naming concepts.\\\",\");\n\tv456 = System.Text.StringBuilder::AppendLine(v57, \"    \\\"reasoning\\\": \\\"Why these concepts matched.\\\",\");\n\tv465 = System.Text.StringBuilder::AppendLine(v57, \"    \\\"missingTerm\\\": \\\"\\\",\");\n\tv474 = System.Text.StringBuilder::AppendLine(v57, \"    \\\"missingReason\\\": \\\"\\\"\");\n\tv483 = System.Text.StringBuilder::AppendLine(v57, \"  }\");\n\tv488 = System.Text.StringBuilder::AppendLine(v57);\n\tv494 = System.Text.StringBuilder::AppendLine(v57, \"  Failure shape:\");\n\tv498 = System.Text.StringBuilder::AppendLine(v57, \"  {\");\n\tv504 = System.Text.StringBuilder::AppendLine(v57, \"    \\\"outcome\\\": \\\"report_missing\\\",\");\n\tv510 = System.Text.StringBuilder::AppendLine(v57, \"    \\\"conceptIds\\\": [],\");\n\tv516 = System.Text.StringBuilder::AppendLine(v57, \"    \\\"enrichedPrompt\\\": \\\"\\\",\");\n\tv522 = System.Text.StringBuilder::AppendLine(v57, \"    \\\"reasoning\\\": \\\"\\\",\");\n\tv528 = System.Text.StringBuilder::AppendLine(v57, \"    \\\"missingTerm\\\": \\\"the unmatched term as the designer wrote it\\\",\");\n\tv534 = System.Text.StringBuilder::AppendLine(v57, \"    \\\"missingReason\\\": \\\"why no concept in the DB matches\\\"\");\n\tv538 = System.Text.StringBuilder::AppendLine(v57, \"  }\");\n\tv541 = System.Text.StringBuilder::AppendLine(v57);\n\tv547 = System.Text.StringBuilder::AppendLine(v57, \"If the concept DB is empty AND the prompt references any gameplay concept, fail with\");\n\tv553 = System.Text.StringBuilder::AppendLine(v57, \"report_missing. A prompt with no detectable concept references may commit with an empty\");\n\tv559 = System.Text.StringBuilder::AppendLine(v57, \"conceptIds array and the original prompt as enrichedPrompt.\");\n\tv131 = System.Text.StringBuilder::ToString(v131);\n\treturn v57;\nL_00AC:\n\tv57 = new System.Text.StringBuilder();\n\tSystem.Text.StringBuilder::.ctor(v57);\n")]
